'use strict';
const fs=require('fs'),path=require('path'),assert=require('assert');
const Yahoo=require('../js/yahoo-season-v1.js'),Season=require('../js/season-command-center-v1.js');
const fixture=JSON.parse(fs.readFileSync(path.join(__dirname,'fixtures/yahoo/real_nested_season_2026_sanitized.json'),'utf8'));
const simpleBundle=JSON.parse(fs.readFileSync(path.join(__dirname,'fixtures/yahoo/league_bundle_2026.json'),'utf8'));
const tests=[];function test(name,fn){tests.push({name,fn});}
const userKey='470.l.164770.t.2',opponentKey='470.l.164770.t.7';

test('real numeric-key discovery returns four unique 2026 NFL leagues',()=>{const rows=Yahoo.normalizeLeagueList(fixture.discovery,{season:2026});assert.strictEqual(rows.length,4);assert.deepStrictEqual(rows.map(row=>row.leagueKey).sort(),['470.l.1469342','470.l.1528653','470.l.164770','470.l.385832']);assert.strictEqual(new Set(rows.map(row=>row.leagueKey)).size,4);});
test('discovery retains representative league metadata without count phantoms',()=>{const rows=Yahoo.normalizeLeagueList(fixture.discovery,{season:2026}),league=rows.find(row=>row.leagueKey==='470.l.164770');assert.deepStrictEqual({name:league.name,teamCount:league.teamCount,season:league.season,gameCode:league.gameCode,currentWeek:league.currentWeek,draftStatus:league.draftStatus},{name:'SQUAAA! ROYAL RUMBLE 2026-2027',teamCount:10,season:2026,gameCode:'nfl',currentWeek:2,draftStatus:'postdraft'});assert(!rows.some(row=>row.leagueKey==='count'));});
test('requested season and supported game code filters still apply',()=>{const rows=Yahoo.normalizeLeagueList({leagues:[{leagueKey:'nfl-2026',name:'NFL 2026',season:'2026',gameCode:'nfl'},{leagueKey:'nfl-2025',name:'NFL 2025',season:'2025',gameCode:'nfl'},{leagueKey:'mlb-2026',name:'MLB 2026',season:'2026',gameCode:'mlb'}]},{season:2026});assert.deepStrictEqual(rows.map(row=>row.leagueKey),['nfl-2026']);});
test('already-normalized league arrays remain compatible',()=>{const rows=Yahoo.normalizeLeagueList({leagues:[{leagueKey:'simple',leagueId:'1',name:'Simple League',season:2026,gameCode:'nfl',teamCount:8,currentWeek:0}]},{season:2026});assert.strictEqual(rows.length,1);assert.strictEqual(rows[0].leagueKey,'simple');assert.strictEqual(rows[0].currentWeek,0);});
test('buildSeasonSnapshot still resolves the single-league sync payload',()=>{const snapshot=Yahoo.buildSeasonSnapshot(simpleBundle,{profile:{id:'fixture',season:2026,actualTeams:10,settings:{}},canonicalPlayers:[],aliases:{},archives:[]});assert.strictEqual(snapshot.league.leagueKey,'461.l.10001');assert.strictEqual(snapshot.league.name,'Sanitized Test League');});
test('real numeric-key standings normalize to ten unique teams',()=>{const rows=Yahoo.normalizeStandings(fixture.standings);assert.strictEqual(rows.length,10);assert.strictEqual(new Set(rows.map(row=>row.teamKey)).size,10);});
test('captured user standing retains record rank and points',()=>{const row=Yahoo.normalizeStandings(fixture.standings).find(item=>item.teamKey===userKey);assert.deepStrictEqual({rank:row.rank,wins:row.wins,losses:row.losses,ties:row.ties,percentage:row.percentage,pointsFor:row.pointsFor,pointsAgainst:row.pointsAgainst,playoffSeed:row.playoffSeed},{rank:9,wins:0,losses:1,ties:0,percentage:0,pointsFor:116.58,pointsAgainst:188.83,playoffSeed:9});});
test('count metadata does not create a phantom standing',()=>{const rows=Yahoo.normalizeStandings(fixture.standings);assert(!rows.some(row=>row.teamKey==='count'||!row.teamKey));});
test('real scoreboard normalizes five week-two matchups',()=>{const result=Yahoo.normalizeMatchups(fixture.matchups);assert.strictEqual(result.week,2);assert.strictEqual(result.matchups.length,5);assert.strictEqual(new Set(result.matchups.map(row=>row.matchupId)).size,5);});
test('user and opponent scores stay attached to their team keys',()=>{const result=Yahoo.normalizeMatchups(fixture.matchups),matchup=result.matchups.find(row=>row.teamKeys.includes(userKey)),user=matchup.teams.find(row=>row.teamKey===userKey),opponent=matchup.teams.find(row=>row.teamKey===opponentKey);assert.strictEqual(matchup.status,'midevent');assert.deepStrictEqual(user,{teamKey:userKey,actualPoints:0,weeklyProjectedPoints:144.54,projectedPoints:144.54,currentProjectedFinal:null,winProbability:0.22});assert.deepStrictEqual(opponent,{teamKey:opponentKey,actualPoints:91.9,weeklyProjectedPoints:139.57,projectedPoints:139.57,currentProjectedFinal:null,winProbability:0.78});});
test('numeric Yahoo count fields do not create phantom matchups or teams',()=>{const result=Yahoo.normalizeMatchups(fixture.matchups);assert.strictEqual(result.matchups.length,5);assert(result.matchups.every(row=>row.teams.length===2&&row.teamKeys.length===2));});
test('zero strings numbers and decimals remain zero while missing remains null',()=>{const result=Yahoo.normalizeMatchups({week:'2',matchups:[{teamKeys:['a','b']},{teams:[{teamKey:'c',actualPoints:'0',projectedPoints:'0.00',winProbability:0},{teamKey:'d',actualPoints:0,projectedPoints:'116.58',winProbability:'1'}]}]});assert.deepStrictEqual(result.matchups[0].teams,[{teamKey:'a',actualPoints:null,weeklyProjectedPoints:null,projectedPoints:null,currentProjectedFinal:null,winProbability:null},{teamKey:'b',actualPoints:null,weeklyProjectedPoints:null,projectedPoints:null,currentProjectedFinal:null,winProbability:null}]);assert.deepStrictEqual(result.matchups[1].teams,[{teamKey:'c',actualPoints:0,weeklyProjectedPoints:0,projectedPoints:0,currentProjectedFinal:null,winProbability:0},{teamKey:'d',actualPoints:0,weeklyProjectedPoints:116.58,projectedPoints:116.58,currentProjectedFinal:null,winProbability:1}]);});
test('standing numeric strings coerce and missing values remain null',()=>{const rows=Yahoo.normalizeStandings({standings:[{teamKey:'a',wins:'1',losses:0,ties:'0',pointsFor:'116.58'},{teamKey:'b'}]});assert.deepStrictEqual({wins:rows[0].wins,losses:rows[0].losses,ties:rows[0].ties,pointsFor:rows[0].pointsFor},{wins:1,losses:0,ties:0,pointsFor:116.58});assert.strictEqual(rows[1].wins,null);assert.strictEqual(rows[1].pointsFor,null);});
test('team-side attribution is independent of Yahoo container order',()=>{const swapped=JSON.parse(JSON.stringify(fixture.matchups)),teams=swapped.fantasy_content.league[1].scoreboard['0'].matchups['1'].matchup['0'].teams,temp=teams['0'];teams['0']=teams['1'];teams['1']=temp;const matchup=Yahoo.normalizeMatchups(swapped).matchups.find(row=>row.teamKeys.includes(userKey)),user=matchup.teams.find(row=>row.teamKey===userKey),opponent=matchup.teams.find(row=>row.teamKey===opponentKey);assert.strictEqual(user.projectedPoints,144.54);assert.strictEqual(opponent.actualPoints,91.9);});
test('Season Command Center resolves container matchups and every live value by stable team key',()=>{const standings=Yahoo.normalizeStandings(fixture.standings),matchups=Yahoo.normalizeMatchups(fixture.matchups),snapshot={schema:'fantasy-hq-yahoo-season-1',provider:'Yahoo',profileId:'fixture-profile',fetchedAt:'2026-09-18T12:00:00Z',league:{name:'Sanitized Regression League',teamCount:10,currentWeek:2},settings:{scoringType:'half-ppr'},teams:[{teamKey:userKey,name:'User Team',isUser:true,managerName:'Gerard',roster:[]},{teamKey:opponentKey,name:'Opponent Team',isUser:false,roster:[]}],userTeamKey:userKey,standings,matchups,availablePlayers:[],transactions:[],subsystemErrors:{},draftLinkage:{status:'NOT_LINKED'}},model=Season.buildModel({state:{snapshot,sync:{status:'CURRENT',lastSuccessfulSyncAt:snapshot.fetchedAt}},profile:{id:'fixture-profile'}});assert.strictEqual(model.userTeam.isUser,true);assert.strictEqual(model.userTeam.managerName,'Gerard');assert.deepStrictEqual({rank:model.standing.rank,wins:model.standing.wins,losses:model.standing.losses,pointsFor:model.standing.pointsFor,pointsAgainst:model.standing.pointsAgainst},{rank:9,wins:0,losses:1,pointsFor:116.58,pointsAgainst:188.83});assert.strictEqual(model.matchup.status,'midevent');assert.strictEqual(model.opponent.teamKey,opponentKey);assert.deepStrictEqual(model.userMatchupSide,{teamKey:userKey,actualPoints:0,weeklyProjectedPoints:144.54,projectedPoints:144.54,currentProjectedFinal:null,winProbability:0.22});assert.deepStrictEqual(model.opponentMatchupSide,{teamKey:opponentKey,actualPoints:91.9,weeklyProjectedPoints:139.57,projectedPoints:139.57,currentProjectedFinal:null,winProbability:0.78});});
test('Season matchup accessor supports legacy direct arrays without creating another canonical shape',()=>{const row={teamKeys:[userKey,opponentKey],teams:[]};assert.deepStrictEqual(Season.getSnapshotMatchups({matchups:[row]}),[row]);assert.deepStrictEqual(Season.getSnapshotMatchups({matchups:{week:2,matchups:[row]}}),[row]);assert.deepStrictEqual(Season.getSnapshotMatchups({matchups:{week:2}}),[]);});
test('Yahoo probability remains source data and is not proprietary authority',()=>{const matchup=Yahoo.normalizeMatchups(fixture.matchups).matchups.find(row=>row.teamKeys.includes(userKey));assert(Object.hasOwn(matchup.teams[0],'winProbability'));assert(!Object.hasOwn(matchup,'championshipEquity'));assert(!Object.hasOwn(matchup,'confidence'));});

let passed=0,failures=[];for(const entry of tests){try{entry.fn();passed++;}catch(error){failures.push({name:entry.name,error:error.stack||error.message});}}
console.log(JSON.stringify({passCount:passed,failCount:failures.length,failures}));if(failures.length)process.exit(1);
